import threading
from collections import OrderedDict

class Engine:
    def __init__(self):
        self._lock = threading.Lock()
        self._tasks = OrderedDict()
        self._next_id = 1
        self._leases = {}
        self._owner_tasks = {}
        self._results = {}

    def submit(self, owner, key):
        with self._lock:
            # Check for existing active task with same owner and key
            for task_id, task in self._tasks.items():
                if task['owner'] == owner and task['key'] == key:
                    if task['status'] in ('queued', 'running'):
                        return task_id
            # Create new task
            task_id = self._next_id
            self._next_id += 1
            task = {'owner': owner, 'key': key, 'status': 'queued', 'result': None, 'created_at': None}
            self._tasks[task_id] = task
            if owner not in self._owner_tasks:
                self._owner_tasks[owner] = OrderedDict()
            self._owner_tasks[owner][task_id] = None
            return task_id

    def claim(self, worker, now, ttl):
        with self._lock:
            if ttl <= 0:
                return None
            # Find first queued task or expired running task (in insertion order)
            for task_id, task in self._tasks.items():
                if task['status'] == 'queued':
                    # Claim queued task
                    token = uuid.uuid4()
                    self._leases[task_id] = {'worker': worker, 'token': token, 'ttl': ttl, 'claimed_at': now}
                    task['status'] = 'running'
                    task['created_at'] = now
                    return {'task_id': task_id, 'worker': worker, 'token': token, 'owner': task['owner']}
                elif task['status'] == 'running' and task['created_at'] is not None:
                    # Check if expired
                    if now - task['created_at'] > ttl:
                        # Expired running task is eligible for re-claim
                        token = uuid.uuid4()
                        self._leases[task_id] = {'worker': worker, 'token': token, 'ttl': ttl, 'claimed_at': now}
                        return {'task_id': task_id, 'worker': worker, 'token': token, 'owner': task['owner']}
            return None

    def cancel(self, owner, task_id):
        with self._lock:
            if task_id not in self._tasks:
                return False
            if self._tasks[task_id]['owner'] != owner:
                raise PermissionError(f"Cannot cancel task {task_id} owned by {owner}")
            if self._tasks[task_id]['status'] in ('completed', 'cancelled'):
                return False
            # Cancel the task
            self._tasks[task_id]['status'] = 'cancelled'
            if task_id in self._leases:
                del self._leases[task_id]
            return True

    def publish(self, lease, now, result):
        with self._lock:
            # Check that lease is valid and unexpired
            if lease['task_id'] not in self._leases:
                return False
            stored_lease = self._leases[lease['task_id']]
            if stored_lease['worker'] != lease['worker']:
                return False
            if stored_lease['token'] != lease['token']:
                return False
            if stored_lease['ttl'] > 0 and now - stored_lease['claimed_at'] > stored_lease['ttl']:
                return False
            # Check that task is still active
            if lease['task_id'] not in self._tasks:
                return False
            if self._tasks[lease['task_id']]['status'] not in ('queued', 'running'):
                return False
            # Publish the result
            self._tasks[lease['task_id']]['status'] = 'completed'
            self._tasks[lease['task_id']]['result'] = result
            # Remove the lease
            del self._leases[lease['task_id']]
            # Store result for results() method
            owner = lease['owner']
            if owner not in self._results:
                self._results[owner] = []
            self._results[owner].append((lease['task_id'], result))
            return True

    def results(self, owner):
        with self._lock:
            if owner not in self._results:
                return []
            # Return a deep copy
            import copy
            return copy.deepcopy(self._results[owner])

